/* Standalone personal prototype. All calculations and records stay in the browser. */
(function () {
  'use strict';
  const E=window.KbitEngine,$=id=>document.getElementById(id),KEY='kbit-slot-demo-v1';
  const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',warehouse:'<path d="m3 9 9-5 9 5v11H3Z"/><path d="M8 20v-8h8v8M8 16h8M11 8h2"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',checklist:'<rect x="5" y="4" width="15" height="17" rx="2"/><path d="M9 4V2m6 2V2M8 10l1.5 1.5L12 9m2 2h3m-9 6 1.5 1.5L12 16m2 2h3"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 5v6h6m3-4v6l4 2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3 2.4c-.5.3-.5.9-.5 1.6M12 17h.01"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',box:'<path d="m12 3 9 5-9 5-9-5Zm-9 5v10l9 5 9-5V8M12 13v10M7.5 5.5l9 5"/>',position:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M4 10h16M10 4v16"/>',orders:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2ZM9 8h6m-6 4h6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',file:'<path d="M14 2H5v20h14V7ZM14 2v6h5M8 12h8m-8 4h6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6m-5 4a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',circlecheck:'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
  const icon=name=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.box)+'</svg>';
  const escape=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const number=value=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:0}).format(value);
  const percentage=value=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:1,maximumFractionDigits:1}).format(value);
  const formatDate=value=>new Intl.DateTimeFormat('es-PE',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Lima'}).format(new Date(value));
  function fresh(){const data=E.demo();return{version:1,...data,source:'Pedidos de ejemplo',synthetic:true,rules:{maxMoves:6,cleaningZone:true,pinned:[10]},plan:null,history:[]};}
  let state=fresh(),page='almacen',mapMode='actual',busy=false,toastTimer;
  let visualProps=null,visualController=null;
  try { const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.version===1&&saved.assignment?.length===30&&new Set(saved.assignment).size===30&&saved.orders?.length&&saved.rules?.pinned&&Array.isArray(saved.history))state=saved; } catch {}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('El navegador no pudo guardar los cambios. Puedes exportar el plan.');}}
  function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
  function button(label,action,ico='arrow',className='btn',extra=''){return '<button type="button" class="'+className+'" data-action="'+action+'" '+extra+'>'+icon(ico)+'<span>'+label+'</span></button>';}
  function heading(eyebrow,title,subtitle,actions=''){return '<div class="page-heading"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p>'+subtitle+'</p></div><div class="actions">'+actions+'</div></div>';}
  function stat(label,value,note,ico){return '<div class="stat"><div class="stat-top"><span>'+label+'</span>'+icon(ico)+'</div><div class="stat-value">'+value+'</div><div class="stat-note">'+note+'</div></div>';}
  function stats(){return '<div class="stat-grid">'+stat('Productos activos','30','6 familias de productos','box')+stat('Ubicaciones','32','4 pasillos · 8 posiciones','position')+stat('Pedidos analizados',number(state.orders.length),state.synthetic?'Historial sintético de ejemplo':'Historial importado por CSV','orders')+stat('Posiciones libres','2','Incluye 1 reserva temporal','layers')+'</div>';}
  function map2D(assignment=state.assignment,highlight=[],tabs=false){
    const occupancy=Array(32).fill(null);assignment.forEach((slot,id)=>occupancy[slot]=E.products[id]);
    const columns='ABCD'.split('').map((aisle,a)=>'<div class="aisle"><div class="aisle-label"><b>Pasillo '+aisle+'</b><span>'+String(a+1).padStart(2,'0')+'</span></div><div class="aisle-slots">'+Array.from({length:8},(_,row)=>{const slot=a*8+row,p=occupancy[slot],changed=p&&highlight.includes(p.id);return '<button type="button" class="slot '+(p?'family-'+p.family:'empty')+(changed?' changed':'')+(p&&state.rules.pinned.includes(p.id)?' pinned':'')+'" data-action="slot" data-slot="'+slot+'" aria-label="'+escape(E.slotName(slot)+': '+(p?p.name+(state.rules.pinned.includes(p.id)?', producto fijo':''):slot===31?'Reserva para movimientos temporales':'Ubicación libre'))+'">'+(p?'<span class="slot-mark"></span>':'')+'<span class="slot-text"><span class="slot-code">'+E.slotName(slot)+(p&&state.rules.pinned.includes(p.id)?' · FIJO':'')+'</span><span class="sku-name">'+(p?escape(p.name):slot===31?'Temporal':'Libre')+'</span></span></button>';}).join('')+'</div></div>').join('');
    return '<section class="panel"><div class="panel-head"><div><h2>Distribución del almacén</h2><p>'+(tabs&&mapMode==='propuesta'?'Los productos resaltados cambian de ubicación.':'Selecciona una ubicación para ver su producto.')+'</p></div>'+(tabs?'<div class="map-tabs" role="group" aria-label="Distribución mostrada"><button type="button" data-action="map-actual" class="'+(mapMode==='actual'?'active':'')+'" aria-pressed="'+(mapMode==='actual')+'">Actual</button><button type="button" data-action="map-propuesta" class="'+(mapMode==='propuesta'?'active':'')+'" aria-pressed="'+(mapMode==='propuesta')+'">Propuesta</button></div>':'<span class="pill">'+icon('position')+' Vista superior</span>')+'</div><div class="warehouse"><div class="warehouse-aisles">'+columns+'</div><div class="warehouse-corridor"><span>← Pasillo transversal de acceso →</span><span class="packing">'+icon('box')+' Empaque / salida</span></div></div><div class="map-legend"><span><i class="legend-dot" style="background:#abc79a"></i>Ubicación ocupada</span><span><i class="legend-dot available"></i>Libre / temporal</span>'+(tabs?'<span><i class="legend-dot" style="background:#d4eaba"></i>Producto reubicado</span>':'')+'<span class="hint">'+icon('lock')+' Marca de producto fijo</span></div></section>';
  }
  function map(assignment=state.assignment,highlight=[],tabs=false){
    const flat=map2D(assignment,highlight,tabs);
    if(!window.KbitVisual)return flat;
    visualProps={assignment:[...assignment],orders:state.orders,pinned:state.rules.pinned,highlight,tabs,mode:mapMode,flat};
    return window.KbitVisual.panel(visualProps);
  }
  function simulationPlan(){
    if(state.plan&&!state.plan.completed)return {...state.plan,initial:[...state.assignment],tasks:state.plan.tasks.filter(task=>!task.done).map(task=>({...task}))};
    return E.optimize(state.assignment,state.orders,state.rules);
  }
  function dataPanel(){return '<section class="panel details-panel"><h3>Datos de tu operación</h3><div class="detail-row"><span>Catálogo</span><strong>30 productos de ejemplo</strong></div><div class="detail-row"><span>Distribución</span><strong>4 pasillos / 32 ubicaciones</strong></div><div class="detail-row"><span>Zona de limpieza</span><strong>'+(state.rules.cleaningZone?'Pasillo D':'Sin restricción')+'</strong></div><div class="detail-row"><span>Productos fijos</span><strong>'+state.rules.pinned.length+' protegidos</strong></div><div class="file-chip">'+icon('file')+'<div>'+escape(state.source)+'<small>'+state.orders.length+' pedidos · '+(state.synthetic?'datos sintéticos':'importados en este navegador')+'</small></div></div></section>';}
  function introSteps(){return '<div class="workflow-strip"><div class="workflow-step"><span class="workflow-number">1</span><div><strong>Conecta tus pedidos</strong><p>Empieza con el ejemplo o carga un CSV.</p></div></div><div class="workflow-step"><span class="workflow-number">2</span><div><strong>Define lo que puede cambiar</strong><p>Limita las reubicaciones y fija productos.</p></div></div><div class="workflow-step"><span class="workflow-number">3</span><div><strong>Ejecuta un plan claro</strong><p>Confirma cada movimiento, paso a paso.</p></div></div></div>';}
  function overview(){
    const active=state.plan&&!state.plan.completed;
    return heading('EXPLORADOR DEL ALMACÉN','Tu operación, en perspectiva.','Explora tu almacén y mira cómo se transforma, movimiento a movimiento.',button('Ver demo','visual-demo','spark')+button(active?'Continuar plan':'Preparar turno',active?'tasks':'plan','arrow','btn btn-primary'))+
      '<div class="content-grid"><div>'+map()+
      '<div class="visual-top-stats"><span><i class="mini-dot"></i><b>30</b> productos</span><i class="stat-divider"></i><span><b>4</b> pasillos</span><i class="stat-divider"></i><span><b>32</b> posiciones</span><i class="stat-divider"></i><span><b>'+state.orders.length+'</b> pedidos de ejemplo</span></div></div>'+
      '<aside class="side-stack"><section class="next-action"><span class="action-icon">'+icon('spark')+'</span><div class="eyebrow">DALE PLAY A TU PRÓXIMO TURNO</div><h2>Los cambios,<br>a la vista.</h2><p>Observa cómo los productos encuentran un mejor lugar. Tú controlas la vista y el ritmo.</p>'+button('Simular reubicaciones','visual-demo','arrow','btn btn-lime btn-full')+'</section>'+
      '<section class="panel visual-use-guide"><h3>Una demo para explorar.</h3><div class="visual-use-step"><span class="use-num">01</span><div><strong>Gira y acércate</strong><p>Arrastra el espacio y cambia el punto de vista.</p></div></div><div class="visual-use-step"><span class="use-num">02</span><div><strong>Descubre cada producto</strong><p>Selecciona una caja, consulta su demanda y sus conexiones.</p></div></div><div class="visual-use-step"><span class="use-num">03</span><div><strong>Mira la transformación</strong><p>Reproduce, pausa y vuelve a ver las reubicaciones.</p></div></div></section>'+
      '<p class="visual-micro-note">'+icon('info')+'Modelo ilustrativo. Explora los productos y los cambios del plan desde esta vista.</p></aside></div>';
  }
  function rulePanel(){return '<aside class="side-stack rules-stack"><section class="panel"><div class="panel-head"><div><h2>Las reglas de tu turno</h2><p>El plan se adapta a lo que puedes mover.</p></div>'+icon('spark')+'</div><form class="rule-form" id="rules-form"><div class="field-group"><div class="range-label"><label class="field-label" for="max-moves">Productos a reubicar, máximo</label><span class="range-value"><output id="moves-output" for="max-moves">'+state.rules.maxMoves+'</output><small>SKUs</small></span></div><input id="max-moves" name="maxMoves" type="range" min="2" max="12" step="2" value="'+state.rules.maxMoves+'"><p class="field-help">Cuenta productos que cambian de posición. Los pasos temporales se muestran por separado.</p></div><div class="field-group"><label class="check-label"><input type="checkbox" id="cleaning-zone" '+(state.rules.cleaningZone?'checked':'')+'><span>Mantener limpieza en pasillo D<small>Los productos de limpieza conservan su zona asignada.</small></span></label></div><div class="field-group pin-group"><label class="field-label" for="pin-search">Productos que no se mueven</label><input id="pin-search" type="search" placeholder="Buscar producto…" class="pin-search" aria-label="Buscar producto para fijar"><div class="pin-list">'+E.products.map(p=>'<label data-product-name="'+escape(p.name.toLowerCase())+'"><input type="checkbox" name="pinned" value="'+p.id+'" '+(state.rules.pinned.includes(p.id)?'checked':'')+'>'+escape(p.name)+'<span>'+E.slotName(state.assignment[p.id])+'</span></label>').join('')+'</div></div><div class="rule-submit"><button type="submit" class="btn btn-primary btn-full" '+(busy?'disabled':'')+'>'+(busy?'<span class="spin">'+icon('refresh')+'</span> Generando plan…':icon('spark')+' Generar plan de turno')+'</button><p class="form-foot">Cálculo local · sin cambiar tu almacén todavía</p></div></form></section><p class="quiet-note">'+icon('info')+'D08 queda reservado como espacio temporal. El plan incluye la secuencia para realizar los intercambios.</p></aside>';}
  function planning(){
    const inProgress=state.plan?.tasks.some(t=>t.done)&&!state.plan.completed;if(inProgress)return heading('PREPARAR TURNO','Tu turno ya está en marcha.','Completa las tareas del plan actual antes de generar otro.')+empty('checklist','Hay movimientos en ejecución','El plano refleja los movimientos ya confirmados. Continúa con la secuencia pendiente.','Continuar tareas','tasks');
    if(state.plan&&!state.plan.completed&&state.plan.tasks.length)return review();
    return heading('PREPARAR TURNO','Un buen turno empieza con un plan.','Elige cuánto puedes cambiar. Kbit encuentra una distribución que respeta tus reglas.',button('Importar pedidos','import','upload'))+'<div class="notice">'+icon('info')+'<span>Los productos que aparecen juntos en los pedidos se intentan acercar. Puedes bloquear productos y limitar las reubicaciones.</span></div><div class="content-grid"><div>'+map()+introSteps()+'</div>'+rulePanel()+'</div>';
  }
  function resultStats(){const p=state.plan;return '<div class="stat-grid">'+stat('Mejora del índice',percentage(p.improvement)+'<small>%</small>','Cercanía ponderada por pedidos','spark')+stat('Productos reubicados',p.moved+'<small>/ '+p.rules.maxMoves+'</small>','Dentro del límite configurado','box')+stat('Movimientos del plan',p.tasks.length,'Incluye pasos temporales','checklist')+stat('Productos protegidos',p.rules.pinned.length,'Conservan su ubicación','lock')+'</div>';}
  function changedProducts(){const p=state.plan;return '<section class="panel panel-gap"><div class="panel-head"><div><h2>Estos productos cambian de lugar</h2><p>Una propuesta concreta para el próximo turno.</p></div><span class="pill">'+p.moved+' productos</span></div><div class="table-wrap"><table class="result-table"><thead><tr><th>Producto</th><th>Actual</th><th>Propuesta</th></tr></thead><tbody>'+E.products.filter(product=>p.initial[product.id]!==p.target[product.id]).map(product=>'<tr><td><strong>'+escape(product.name)+'</strong><br><span class="small muted">'+product.code+'</span></td><td><span class="code-pill">'+E.slotName(p.initial[product.id])+'</span></td><td><span class="code-pill">'+E.slotName(p.target[product.id])+'</span></td></tr>').join('')+'</tbody></table></div></section>';}
  function review(){const p=state.plan,highlight=E.products.filter(product=>p.initial[product.id]!==p.target[product.id]).map(product=>product.id);return heading('PLAN DE TURNO · LISTO PARA REVISAR','Tu próximo turno, mejor organizado.','La propuesta está lista. Convierte estos cambios en tareas para tu equipo.',button('Ajustar reglas','adjust','refresh')+button('Ver tareas de movimiento','tasks','arrow','btn btn-primary'))+resultStats()+'<div class="content-grid"><div>'+map(mapMode==='propuesta'?p.target:state.assignment,highlight,true)+changedProducts()+'</div><aside class="side-stack"><section class="next-action"><span class="action-icon">'+icon('circlecheck')+'</span><div class="eyebrow">PROPUESTA CALCULADA</div><h2>'+percentage(p.improvement)+'% de mejora<br>en el índice.</h2><p>'+p.moved+' productos cambian de lugar. Kbit los convierte en '+p.tasks.length+' movimientos ordenados, con destinos libres.</p>'+button('Empezar los movimientos','tasks','arrow','btn btn-lime btn-full')+'</section><section class="panel details-panel"><h3>La comparación, clara</h3><div class="detail-row"><span>Índice actual</span><strong>'+number(p.before)+'</strong></div><div class="detail-row"><span>Índice propuesto</span><strong>'+number(p.after)+'</strong></div><div class="detail-row"><span>Zona de limpieza</span><strong>'+(p.rules.cleaningZone?'Respetada':'No aplicada')+'</strong></div><div class="detail-row"><span>Motor utilizado</span><strong>Heurística clásica local</strong></div>'+button('Descargar plan CSV','export','download','btn btn-full')+'</section><p class="quiet-note">'+icon('info')+'Un índice menor indica mayor cercanía entre productos asociados. Este porcentaje no equivale a tiempo o dinero ahorrado.</p></aside></div>';}
  function empty(ico,title,description,label,action){return '<section class="panel"><div class="empty-state"><div class="empty-symbol">'+icon(ico)+'</div><h2>'+title+'</h2><p>'+description+'</p>'+button(label,action,'arrow','btn btn-primary')+'</div></section>';}
  function taskPage(){
    const p=state.plan;if(!p||!p.tasks.length)return heading('TAREAS DE MOVIMIENTO','Cada movimiento, claro.','Aquí aparecen las instrucciones para ejecutar tu plan.')+empty('checklist','Tu siguiente plan empieza aquí.','Configura las reglas y genera una propuesta para convertirla en tareas listas para ejecutar.','Preparar turno','plan');
    const done=p.tasks.filter(t=>t.done).length,next=p.tasks.find(t=>!t.done),progress=Math.round(done/p.tasks.length*100);
    const complete=p.completed?'<div class="success-panel">'+icon('circlecheck')+'<div><h2>Un turno mejor organizado.</h2><p>Todos los movimientos están confirmados. La nueva distribución ya aparece en tu almacén.</p></div>'+button('Ver mi almacén','warehouse','grid','btn')+'</div>':'';
    const tasks=p.tasks.map(t=>{const product=E.products[t.product];return '<article class="task '+(t.done?'done':'')+'"><span class="task-index">'+(t.done?icon('check'):String(t.id).padStart(2,'0'))+'</span><div><h3>'+escape(product.name)+'</h3><p>'+product.code+(t.temporary?' · Paso temporal para liberar un destino':' · Reubicación de producto')+'</p><div class="task-route"><b>'+E.slotName(t.from)+'</b>'+icon('arrow')+'<b>'+E.slotName(t.to)+'</b>'+(t.temporary?'<span class="pill">Temporal</span>':'')+'</div></div>'+(t.done?'<span class="pill">'+icon('check')+' Confirmado</span>':next&&next.id===t.id?button('Confirmar movimiento','confirm-task','check','btn btn-primary','data-task="'+t.id+'"'):'<span class="task-future">Espera el paso anterior</span>')+'</article>';}).join('');
    return heading('EJECUCIÓN DEL TURNO',p.completed?'Todo en su nuevo lugar.':'Un movimiento a la vez.','Sigue el orden. Confirma cada tarea cuando hayas realizado el movimiento físico.',button('Descargar tareas','export','download'))+complete+'<div class="task-scene">'+map(state.assignment,next?[next.product]:[],false)+'</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Lista de movimientos</h2><p>'+done+' de '+p.tasks.length+' confirmados · '+p.moved+' productos reubicados</p></div><span class="pill">'+(p.completed?'Completado':'En ejecución')+'</span></div><div class="task-list">'+tasks+'</div><div class="review-footer">Los destinos se liberan en secuencia. Confirmar una tarea actualiza el plano en este prototipo.</div></section><aside class="side-stack"><section class="panel details-panel"><h3>Avance del turno</h3><div class="result-number">'+progress+'<small>%</small></div><div class="progress-track" role="progressbar" aria-label="Movimientos completados" aria-valuenow="'+progress+'" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:'+progress+'%"></div></div><p class="small muted">'+done+' / '+p.tasks.length+' movimientos confirmados</p><div class="detail-row"><span>Pendientes</span><strong>'+(p.tasks.length-done)+'</strong></div><div class="detail-row"><span>Producto fijo</span><strong>'+p.rules.pinned.length+' protegidos</strong></div>'+button('Ver distribución actual','warehouse','grid','btn btn-full')+'</section><section class="next-action"><span class="action-icon">'+icon('info')+'</span><h2>Primero mueve.<br>Luego confirma.</h2><p>El prototipo registra tus confirmaciones. Cada paso debe reflejar un movimiento realizado en el almacén.</p></section></aside></div>';
  }
  function historyPage(){
    const content=state.history.length?'<section class="panel"><div class="panel-head"><div><h2>Turnos completados</h2><p>Planes ejecutados en este navegador.</p></div><span class="pill">'+state.history.length+' registros</span></div>'+[...state.history].reverse().map((record,index)=>'<div class="history-row"><div><h3>Plan de turno '+String(state.history.length-index).padStart(2,'0')+'</h3><p>'+formatDate(record.completedAt)+' · '+(record.synthetic?'Pedidos de ejemplo':'Pedidos importados')+'</p></div><div class="history-metrics"><div><strong>'+record.moved+'</strong><small>productos</small></div><div><strong>'+record.tasks+'</strong><small>movimientos</small></div><div><strong>'+percentage(record.improvement)+'%</strong><small>mejora del índice</small></div><span class="pill">'+icon('check')+' Ejecutado</span></div></div>').join('')+'</section>':empty('history','Los cambios dejan un registro.','Cuando confirmes todos los movimientos de un turno, su resultado aparecerá aquí.','Preparar mi primer turno','plan');
    return heading('HISTORIAL DE LA OPERACIÓN','Cada turno cuenta.','Revisa los planes que ya se completaron y los cambios registrados.')+content;
  }
  function render(){
    visualController?.destroy();visualController=null;visualProps=null;
    const titles={almacen:'Mi almacén',planificar:'Preparar turno',tareas:'Tareas',historial:'Historial'};page=Object.hasOwn(titles,location.hash.slice(1))?location.hash.slice(1):'almacen';$('breadcrumb').textContent=titles[page];$('workspace').classList.toggle('immersive-overview',page==='almacen');
    document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    const pending=state.plan?.tasks.filter(t=>!t.done).length||0;$('task-count').hidden=!pending;$('task-count').textContent=pending;
    $('workspace').innerHTML=({almacen:overview,planificar:planning,tareas:taskPage,historial:historyPage}[page])();document.title=titles[page]+' · Kbit Slot';
    if(page==='planificar')wireRules();
    if(visualProps)visualController=window.KbitVisual.mount(visualProps,{getPlan:simulationPlan,onSlot:slotDetails,toast});
  }
  function navigate(target){if(location.hash==='#'+target)render();else location.hash=target;window.scrollTo({top:0,behavior:'instant'});}
  function modal(title,body,actions=''){$('modal-content').innerHTML='<div class="modal-inner"><div class="modal-header"><h2 id="modal-title">'+title+'</h2><button type="button" class="icon-button" data-action="close-modal" aria-label="Cerrar">'+icon('close')+'</button></div>'+body+(actions?'<div class="actions">'+actions+'</div>':'')+'</div>';if(!$('modal').open)$('modal').showModal();}
  function guide(){modal('Así funciona Kbit Slot','<p>Un flujo de software para pasar de los pedidos a los movimientos del almacén.</p>'+[['Conecta los pedidos','Prueba con 180 pedidos sintéticos o importa un archivo CSV del catálogo demo.'],['Prepara el turno','Configura cuántos productos pueden cambiar de lugar, fija productos y genera el plan.'],['Ejecuta los movimientos','Confirma las tareas en orden. El plano y el avance se actualizan con cada confirmación.'],['Revisa el historial','Al completar el turno, el resultado queda registrado en este navegador.']].map((step,i)=>'<div class="step-description"><b>'+(i+1)+'</b><div><h3>'+step[0]+'</h3><p>'+step[1]+'</p></div></div>').join(''),button('Entendido, empezar','close-modal','arrow','btn btn-primary'));}
  function help(){modal('Qué puedes probar','<p><strong>Funciona:</strong> cálculo de un plan clásico, reglas de reubicación, productos fijos, tareas secuenciales, CSV de pedidos, exportación e historial local.</p><p>El catálogo y el plano son de demostración. La importación acepta pedidos de estos 30 SKUs. Los registros se guardan solo en tu navegador.</p><p>Puedes explorar el almacén en 3D, cambiar la cámara, ver demanda y conexiones, y reproducir los movimientos sin confirmar tareas.</p><p>El índice suma la cercanía entre pares de productos que aparecen en un mismo pedido. No mide minutos, productividad real ni ahorro económico.</p><p>Esta versión usa un motor clásico independiente. La integración con WMS, cuentas de usuario, lectores QR y Qiskit se contempla para versiones posteriores.</p><div class="actions">'+button('Ver catálogo de SKUs','catalog','box')+button('Reiniciar demostración','reset-prompt','refresh')+'</div>',button('Cerrar','close-modal','check','btn btn-primary'));}
  function showImport(){if(state.plan?.tasks.some(t=>t.done)&&!state.plan.completed){toast('Completa el turno actual antes de importar nuevos pedidos.');return;}modal('Conecta tus pedidos','<p>Carga un CSV con una línea por producto de cada pedido. Usa los códigos del catálogo de ejemplo.</p><pre>order_id,sku\nPED-001,SKU-001\nPED-001,SKU-006\nPED-002,SKU-003</pre><p class="small">Máximo 2 MB y 5.000 líneas. Se aceptan separadores coma y punto y coma. La carga reemplaza los pedidos del ejemplo e invalida propuestas pendientes.</p><label class="upload-area">'+icon('upload')+'<strong>Selecciona tu archivo de pedidos</strong><small>Los datos se procesan dentro de este navegador.</small><input id="orders-file" type="file" accept=".csv,text/csv" aria-label="Archivo CSV de pedidos"></label><p id="import-error" class="form-error" role="alert" hidden></p>',button('Descargar ejemplo CSV','sample-csv','download')+button('Ver catálogo','catalog','box'));
    $('orders-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('El archivo supera los 2 MB.');const orders=E.parseCSV(await file.text());state.orders=orders;state.source=file.name;state.synthetic=false;state.plan=null;save();$('modal').close();mapMode='actual';render();toast(orders.length+' pedidos importados. Ya puedes generar un plan.');}catch(error){$('import-error').textContent=error.message;$('import-error').hidden=false;event.target.value='';}});
  }
  function slotDetails(slot){const assignment=page==='planificar'&&mapMode==='propuesta'&&state.plan?state.plan.target:state.assignment;const id=assignment.indexOf(slot);if(id<0){modal(E.slotName(slot)+' · '+(slot===31?'Reserva temporal':'Ubicación libre'),'<p>'+(slot===31?'Este espacio se reserva para realizar intercambios sin ocupar un destino con dos productos. El plan genera los pasos temporales necesarios.':'Esta posición está disponible para la propuesta de asignación.')+'</p>',button('Cerrar','close-modal','check','btn btn-primary'));return;}const p=E.products[id];modal(escape(p.name),'<p>'+p.code+' · '+p.category+'</p><div class="detail-row"><span>Ubicación mostrada</span><strong>'+E.slotName(slot)+'</strong></div><div class="detail-row"><span>Presencia en pedidos</span><strong>'+state.orders.filter(order=>order.items.includes(id)).length+' pedidos</strong></div><div class="detail-row"><span>Regla de ubicación</span><strong>'+(state.rules.pinned.includes(id)?'Producto fijo':'Puede reubicarse')+'</strong></div><p class="small" style="margin-top:17px">Puedes cambiar los productos protegidos desde Preparar turno → Ajustar reglas.</p>',button('Cerrar','close-modal','check','btn btn-primary'));}
  function catalog(){modal('Catálogo de demostración','<p>Usa estos códigos en la columna <code>sku</code> del CSV de pedidos.</p><div class="catalog-list">'+E.products.map(p=>'<div class="detail-row"><span>'+escape(p.name)+'</span><strong>'+p.code+'</strong></div>').join('')+'</div>',button('Descargar catálogo','export-catalog','download')+button('Cerrar','close-modal','check','btn btn-primary'));}
  function download(name,text){const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  const csvCell=value=>'"'+String(value).replaceAll('"','""')+'"';
  function exportPlan(){if(!state.plan?.tasks.length){toast('Genera un plan antes de descargar las tareas.');return;}download('kbit-slot-plan.csv',['paso,sku,producto,origen,destino,tipo,estado',...state.plan.tasks.map(task=>[task.id,E.products[task.product].code,E.products[task.product].name,E.slotName(task.from),E.slotName(task.to),task.temporary?'Temporal':'Reubicación',task.done?'Confirmado':'Pendiente'].map(csvCell).join(','))].join('\r\n'));toast('Plan descargado.');}
  function wireRules(){const form=$('rules-form');if(!form)return;$('max-moves').addEventListener('input',event=>$('moves-output').textContent=event.target.value);$('pin-search').addEventListener('input',event=>form.querySelectorAll('[data-product-name]').forEach(label=>label.hidden=!label.dataset.productName.includes(event.target.value.toLowerCase())));
    form.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const rules={maxMoves:Number($('max-moves').value),cleaningZone:$('cleaning-zone').checked,pinned:[...form.querySelectorAll('[name=pinned]:checked')].map(input=>Number(input.value))};busy=true;form.querySelector('button[type=submit]').disabled=true;form.querySelector('button[type=submit]').innerHTML='<span class="spin">'+icon('refresh')+'</span> Calculando distribución…';form.setAttribute('aria-busy','true');await new Promise(resolve=>setTimeout(resolve,80));try{const plan=E.optimize(state.assignment,state.orders,rules);state.rules=rules;if(!plan.tasks.length){state.plan=null;save();modal('Tu distribución ya funciona bien.','<p>No se encontró una mejora con estas reglas y estos pedidos. El sistema mantiene las ubicaciones actuales.</p><p>Puedes permitir más cambios o liberar productos fijos y volver a probar.</p>',button('Volver a las reglas','close-modal','arrow','btn btn-primary'));}else{state.plan={...plan,id:crypto.randomUUID(),createdAt:new Date().toISOString(),synthetic:state.synthetic,completed:false};mapMode='propuesta';save();toast('Plan listo: '+plan.moved+' productos y '+plan.tasks.length+' movimientos.');}}catch(error){toast(error.message);}finally{busy=false;render();window.scrollTo({top:0,behavior:"instant"});}});
  }
  function confirm(id){const task=state.plan?.tasks.find(t=>!t.done);if(!task||task.id!==id)return;try{state.assignment=E.confirmTask(state.assignment,task);task.done=true;task.completedAt=new Date().toISOString();if(state.plan.tasks.every(t=>t.done)){state.plan.completed=true;state.plan.completedAt=task.completedAt;state.history.push({id:state.plan.id,moved:state.plan.moved,tasks:state.plan.tasks.length,improvement:state.plan.improvement,completedAt:task.completedAt,synthetic:state.plan.synthetic});toast('Turno completado. Tu nueva distribución está lista.');}else toast('Movimiento confirmado: '+E.products[task.product].name+'.');save();render();}catch(error){toast(error.message);}}
  document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;if(action==='visual-demo'){visualController?.play();return;}const nav={plan:'planificar',tasks:'tareas',warehouse:'almacen'};if(nav[action])return navigate(nav[action]);if(action==='close-modal')return $('modal').close();if(action==='import')return showImport();if(action==='slot')return slotDetails(Number(target.dataset.slot));if(action==='map-actual'||action==='map-propuesta'){mapMode=action==='map-actual'?'actual':'propuesta';render();return;}if(action==='adjust'){if(state.plan?.tasks.some(task=>task.done)){toast('Completa las tareas pendientes antes de cambiar las reglas.');return;}state.plan=null;mapMode='actual';save();render();return;}if(action==='confirm-task')return confirm(Number(target.dataset.task));if(action==='export')return exportPlan();if(action==='catalog')return catalog();if(action==='sample-csv'){download('pedidos-ejemplo-kbit.csv',['order_id,sku',...E.demo().orders.flatMap(order=>order.items.map(id=>order.id+','+E.products[id].code))].join('\r\n'));return;}if(action==='export-catalog'){download('catalogo-kbit.csv',['sku,producto,familia',...E.products.map(p=>[p.code,p.name,p.category].map(csvCell).join(','))].join('\r\n'));return;}if(action==='reset-prompt'){modal('Volver al ejemplo inicial','<p>Esto reemplaza los pedidos, reglas, planes e historial guardados en este navegador por la demostración inicial.</p>',button('Cancelar','close-modal','close')+button('Reiniciar demostración','reset','refresh','btn btn-primary'));return;}if(action==='reset'){state=fresh();save();mapMode='actual';$('modal').close();navigate('almacen');toast('Demostración reiniciada.');}});
  $('modal').addEventListener('click',event=>{if(event.target===$('modal')){const rect=$('modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('modal').close();}});
  $('help-button').addEventListener('click',help);$('demo-guide').addEventListener('click',guide);document.querySelectorAll('[data-icon]').forEach(element=>element.innerHTML=icon(element.dataset.icon));window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});render();
})();
